    describe("get defaultValue", () => {
        test("initial",                        () => expect(() => new BasicCompanionEnumWithParent()                                        .defaultValue,).toThrow(NullEnumerableException,),)
        test("initial with default parent.A",  () => expect(      new DefaultedCompanionEnumWithParent(BasicEnumWithParent.A,)              .defaultValue,).toBe(BasicEnumWithParent.A,),)
        test("initial with default parent.B",  () => expect(      new DefaultedCompanionEnumWithParent(BasicEnumWithParent.B,)              .defaultValue,).toBe(BasicEnumWithParent.B,),)
        test("initial with default parent.C",  () => expect(      new DefaultedCompanionEnumWithParent(BasicEnumWithParent.C,)              .defaultValue,).toBe(BasicEnumWithParent.C,),)
        test("initial with default parent.D",  () => expect(      new DefaultedCompanionEnumWithParent(BasicEnumWithParent.D,)              .defaultValue,).toBe(BasicEnumWithParent.D,),)
        test("initial with default name A",    () => expect(      new DefaultedNameCompanionEnumWithParent('A',)                            .defaultValue,).toBe(BasicEnumWithParent.A,),)
        test("initial with default name B",    () => expect(      new DefaultedNameCompanionEnumWithParent('B',)                            .defaultValue,).toBe(BasicEnumWithParent.B,),)
        test("initial with default name C",    () => expect(      new DefaultedNameCompanionEnumWithParent('C',)                            .defaultValue,).toBe(BasicEnumWithParent.C,),)
        test("initial with default name D",    () => expect(      new DefaultedNameCompanionEnumWithParent('D',)                            .defaultValue,).toBe(BasicEnumWithParent.D,),)
        test("initial with default ordinal 0", () => expect(      new DefaultedOrdinalCompanionEnumWithParent(0,)                           .defaultValue,).toBe(BasicEnumWithParent.A,),)
        test("initial with default ordinal 1", () => expect(      new DefaultedOrdinalCompanionEnumWithParent(1,)                           .defaultValue,).toBe(BasicEnumWithParent.B,),)
        test("initial with default ordinal 2", () => expect(      new DefaultedOrdinalCompanionEnumWithParent(2,)                           .defaultValue,).toBe(BasicEnumWithParent.C,),)
        test("initial with default ordinal 3", () => expect(      new DefaultedOrdinalCompanionEnumWithParent(3,)                           .defaultValue,).toBe(BasicEnumWithParent.D,),)
        test("after set to null",              () => expect(() => new BasicCompanionEnumWithParent().setDefaultValue(null,)                 .defaultValue,).toThrow(NullEnumerableException,),)
        test("after set to undefined",         () => expect(() => new BasicCompanionEnumWithParent().setDefaultValue(undefined,)            .defaultValue,).toThrow(NullEnumerableException,),)
        test("after set to 0",                 () => expect(      new BasicCompanionEnumWithParent().setDefaultValue(0,)                    .defaultValue,).toBe(BasicEnumWithParent.A,),)
        test("after set to 1",                 () => expect(      new BasicCompanionEnumWithParent().setDefaultValue(1,)                    .defaultValue,).toBe(BasicEnumWithParent.B,),)
        test("after set to 2",                 () => expect(      new BasicCompanionEnumWithParent().setDefaultValue(2,)                    .defaultValue,).toBe(BasicEnumWithParent.C,),)
        test("after set to 3",                 () => expect(      new BasicCompanionEnumWithParent().setDefaultValue(3,)                    .defaultValue,).toBe(BasicEnumWithParent.D,),)
        test("after set to A",                 () => expect(      new BasicCompanionEnumWithParent().setDefaultValue('A',)                  .defaultValue,).toBe(BasicEnumWithParent.A,),)
        test("after set to B",                 () => expect(      new BasicCompanionEnumWithParent().setDefaultValue('B',)                  .defaultValue,).toBe(BasicEnumWithParent.B,),)
        test("after set to C",                 () => expect(      new BasicCompanionEnumWithParent().setDefaultValue('C',)                  .defaultValue,).toBe(BasicEnumWithParent.C,),)
        test("after set to D",                 () => expect(      new BasicCompanionEnumWithParent().setDefaultValue('D',)                  .defaultValue,).toBe(BasicEnumWithParent.D,),)
        test("after set to child.A",           () => expect(      new BasicCompanionEnumWithParent().setDefaultValue(BasicEnum.A,)          .defaultValue,).toBe(BasicEnumWithParent.A,),)
        test("after set to child.B",           () => expect(      new BasicCompanionEnumWithParent().setDefaultValue(BasicEnum.B,)          .defaultValue,).toBe(BasicEnumWithParent.B,),)
        test("after set to child.C",           () => expect(      new BasicCompanionEnumWithParent().setDefaultValue(BasicEnum.C,)          .defaultValue,).toBe(BasicEnumWithParent.C,),)
        test("after set to child.D",           () => expect(      new BasicCompanionEnumWithParent().setDefaultValue(BasicEnum.D,)          .defaultValue,).toBe(BasicEnumWithParent.D,),)
        test("after set to parent.A",          () => expect(      new BasicCompanionEnumWithParent().setDefaultValue(BasicEnumWithParent.A,).defaultValue,).toBe(BasicEnumWithParent.A,),)
        test("after set to parent.B",          () => expect(      new BasicCompanionEnumWithParent().setDefaultValue(BasicEnumWithParent.B,).defaultValue,).toBe(BasicEnumWithParent.B,),)
        test("after set to parent.C",          () => expect(      new BasicCompanionEnumWithParent().setDefaultValue(BasicEnumWithParent.C,).defaultValue,).toBe(BasicEnumWithParent.C,),)
        test("after set to parent.D",          () => expect(      new BasicCompanionEnumWithParent().setDefaultValue(BasicEnumWithParent.D,).defaultValue,).toBe(BasicEnumWithParent.D,),)
    },)
